script:
(function () {
  'use strict';
  // Amortized loan with a chosen payment frequency (p payments a year) and compounding frequency (m).
  //   Rate per payment period: i = (1 + r/m)^(m/p) - 1  (continuous: i = e^(r/p) - 1).
  //   Payment: PMT = L * i / (1 - (1 + i)^-n), n = round(term in months * p / 12); PMT = L / n at 0%.
  //   Effective annual rate = (1 + i)^p - 1.
  // Verified in Node (scratchpad tests/w2loans): $100,000 at 6% monthly for 10 years = $1,110.21/mo,
  //   total interest $33,224.60 (closed form; matches a published calculator's default result);
  //   $20,000 at 8% for 5 years = $405.53/mo; $12,000 at 0% for 12 months = $1,000.00; biweekly with
  //   monthly compounding uses i = 1.005^(12/26) - 1; final balance is exactly 0; extra payments
  //   shorten the loan; blank, negative and 0-term input shows an error, never NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var pct = new Intl.NumberFormat('en-US', { style: 'percent', minimumFractionDigits: 2, maximumFractionDigits: 3 });
  var NAMES = { 12: 'Monthly payment', 24: 'Twice-monthly payment', 26: 'Biweekly payment', 52: 'Weekly payment',
                4: 'Quarterly payment', 2: 'Semiannual payment', 1: 'Yearly payment' };
  var last = null;

  function el(id) { return document.getElementById(id); }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function periodicRate(annualRate, compound, perYear) {
    if (annualRate === 0) return 0;
    if (compound === 0) return Math.exp(annualRate / perYear) - 1;
    return Math.pow(1 + annualRate / compound, compound / perYear) - 1;
  }

  function payment(principal, i, n) {
    if (n <= 0 || principal <= 0) return 0;
    if (i === 0) return principal / n;
    return principal * i / (1 - Math.pow(1 + i, -n));
  }

  function amortize(loan, i, n, extra) {
    var pay = payment(loan, i, n), bal = loan, rows = [], totalInterest = 0, totalPaid = 0;
    for (var k = 1; k <= n && bal > 0.005; k++) {
      var interest = bal * i;
      var principal = Math.min(pay - interest, bal);
      var x = Math.max(0, Math.min(extra, bal - principal));
      bal -= principal + x;
      if (bal < 0.005) bal = 0;
      totalInterest += interest;
      totalPaid += interest + principal + x;
      rows.push({ n: k, interest: interest, principal: principal + x, balance: bal });
    }
    return { payment: pay, rows: rows, totalInterest: totalInterest, totalPaid: totalPaid };
  }

  function duration(months) {
    months = Math.round(months);
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function setText(id, text) { el(id).textContent = text; }

  function clearResults() {
    ['lcPayment', 'lcInterest', 'lcTotal', 'lcPrincipal', 'lcCount', 'lcPayoff', 'lcShare', 'lcEar']
      .forEach(function (id) { setText(id, '–'); });
    el('lcSavings').hidden = true;
    el('lcSchedule').innerHTML = '';
    last = null;
  }

  function renderSchedule() {
    var head = el('lcScheduleHead'), body = el('lcSchedule');
    if (!last) { body.innerHTML = ''; return; }
    var html = [];
    if (el('lcView').value === 'period') {
      head.innerHTML = '<tr><th scope="col">Payment</th><th scope="col">Amount</th><th scope="col">Principal</th><th scope="col">Interest</th><th scope="col">Balance</th></tr>';
      last.rows.forEach(function (row) {
        html.push('<tr><td>' + row.n + '</td><td>' + money.format(row.principal + row.interest) + '</td><td>' +
          money.format(row.principal) + '</td><td>' + money.format(row.interest) + '</td><td>' + money.format(row.balance) + '</td></tr>');
      });
    } else {
      head.innerHTML = '<tr><th scope="col">Year</th><th scope="col">Principal</th><th scope="col">Interest</th><th scope="col">Ending balance</th></tr>';
      var p = 0, intr = 0, per = last.perYear;
      last.rows.forEach(function (row, idx) {
        p += row.principal; intr += row.interest;
        if (row.n % per === 0 || idx === last.rows.length - 1) {
          html.push('<tr><td>' + Math.ceil(row.n / per) + '</td><td>' + money.format(p) + '</td><td>' +
            money.format(intr) + '</td><td>' + money.format(row.balance) + '</td></tr>');
          p = 0; intr = 0;
        }
      });
    }
    body.innerHTML = html.join('');
  }

  function update() {
    var amount = read('lcAmount'), rate = read('lcRate'), years = read('lcYears', true), months = read('lcMonths', true),
        extra = read('lcExtra', true), perYear = parseInt(el('lcFreq').value, 10), compound = parseInt(el('lcCompound').value, 10);
    var error = el('lcError'), msg = '';
    var termMonths = years * 12 + months;
    if (isNaN(amount) || amount <= 0) msg = 'Enter a loan amount greater than $0.';
    else if (isNaN(rate) || rate < 0 || rate > 100) msg = 'Enter an interest rate from 0% to 100%.';
    else if (isNaN(years) || isNaN(months) || years < 0 || months < 0 || years % 1 !== 0 || months % 1 !== 0 || years > 50 || months > 11)
      msg = 'Enter the term as whole years (0 to 50) and months (0 to 11).';
    else if (termMonths < 1) msg = 'Enter a loan term of at least one month.';
    else if (termMonths * perYear / 12 < 1) msg = 'The term is shorter than one payment period. Lengthen the term or pay more often.';
    else if (isNaN(extra) || extra < 0) msg = 'The extra payment cannot be negative.';
    var n = Math.max(1, Math.round(termMonths * perYear / 12));
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var i = periodicRate(rate / 100, compound, perYear);
    var base = amortize(amount, i, n, 0);
    var r = amortize(amount, i, n, extra);

    setText('lcPaymentLabel', NAMES[perYear] || 'Payment');
    setText('lcPayment', money.format(r.payment));
    setText('lcInterest', money.format(r.totalInterest));
    setText('lcTotal', money.format(r.totalPaid));
    setText('lcPrincipal', money.format(amount));
    setText('lcCount', String(r.rows.length));
    setText('lcPayoff', duration(r.rows.length * 12 / perYear));
    setText('lcShare', pct.format(r.totalInterest / amount));
    setText('lcEar', pct.format(Math.pow(1 + i, perYear) - 1));
    el('lcSavings').hidden = !(extra > 0);
    setText('lcSaved', money.format(Math.max(0, base.totalInterest - r.totalInterest)));
    setText('lcFewer', String(Math.max(0, base.rows.length - r.rows.length)));

    last = { rows: r.rows, perYear: perYear };
    renderSchedule();
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('lcForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    el('lcView').addEventListener('change', renderSchedule);
    update();
  });
})();
